00069 static void scalePlane( PelBuf& areaBuf, const int shiftbits, const Pel minval, const Pel maxval)
00070 {
00071   const unsigned width  = areaBuf.width;
00072   const unsigned height = areaBuf.height;
00073   const unsigned stride = areaBuf.stride;
00074         Pel*        img = areaBuf.bufAt(0,0);
00075 
00076   if( 0 == shiftbits )
00077   {
00078     return;
00079   }
00080 
00081   if( shiftbits > 0)
00082   {
00083     for( unsigned y = 0; y < height; y++, img+=stride)
00084     {
00085       for( unsigned x = 0; x < width; x++)
00086       {
00087         img[x] <<= shiftbits;
00088       }
00089     }
00090   }
00091   else if (shiftbits < 0)
00092   {
00093     const int shiftbitsr =- shiftbits;
00094     const Pel rounding = 1 << (shiftbitsr-1);
00095 
00096     for( unsigned y = 0; y < height; y++, img+=stride)
00097     {
00098       for( unsigned x = 0; x < width; x++)
00099       {
00100         img[x] = Clip3(minval, maxval, Pel((img[x] + rounding) >> shiftbitsr));
00101       }
00102     }
00103   }
00104 }
