00127 void VideoIOYuvMem::open(Writer *writer, bool bWriteMode, const int fileBitDepth[MAX_NUM_CHANNEL_TYPE], const int MSBExtendedBitDepth[MAX_NUM_CHANNEL_TYPE], const int internalBitDepth[MAX_NUM_CHANNEL_TYPE] )
00128 {
00129   //NOTE: files cannot have bit depth greater than 16
00130   for(uint32_t ch=0; ch<MAX_NUM_CHANNEL_TYPE; ch++)
00131   {
00132     m_fileBitdepth       [ch] = std::min<uint32_t>(fileBitDepth[ch], 16);
00133     m_MSBExtendedBitDepth[ch] = MSBExtendedBitDepth[ch];
00134     m_bitdepthShift      [ch] = internalBitDepth[ch] - m_MSBExtendedBitDepth[ch];
00135 
00136     if (m_fileBitdepth[ch] > 16)
00137     {
00138       if (bWriteMode)
00139       {
00140         std::cerr << "\nWARNING: Cannot write a yuv file of bit depth greater than 16 - output will be right-shifted down to 16-bit precision\n" << std::endl;
00141       }
00142       else
00143       {
00144         EXIT( "ERROR: Cannot read a yuv file of bit depth greater than 16" );
00145       }
00146     }
00147   }
00148 
00149   if ( bWriteMode )
00150   {
00151       m_writer = writer;
00152   }
00153   else
00154   {
00155       EXIT( "Cannot open input YUV file" );
00156 //    m_cHandle.open( fileName.c_str(), ios::binary | ios::in );
00157 
00158 //    if( m_cHandle.fail() )
00159 //    {
00160 //      EXIT( "Failed to open input YUV file: " << fileName.c_str() );
00161 //    }
00162   }
00163 
00164   return;
00165 }
