00188 #if EXTENSION_360_VIDEO
00189 void VideoIOYuvMem::skipFrames(int numFrames, uint32_t width, uint32_t height, ChromaFormat format)
00190 #else
00191 void VideoIOYuvMem::skipFrames(uint32_t numFrames, uint32_t width, uint32_t height, ChromaFormat format)
00192 #endif
00193 {
00194   if (!numFrames)
00195   {
00196     return;
00197   }
00198 
00199   //------------------
00200   //set the frame size according to the chroma format
00201   streamoff frameSize = 0;
00202   uint32_t wordsize=1; // default to 8-bit, unless a channel with more than 8-bits is detected.
00203   for (uint32_t component = 0; component < getNumberValidComponents(format); component++)
00204   {
00205     ComponentID compID=ComponentID(component);
00206     frameSize += (width >> getComponentScaleX(compID, format)) * (height >> getComponentScaleY(compID, format));
00207     if (m_fileBitdepth[toChannelType(compID)] > 8)
00208     {
00209       wordsize=2;
00210     }
00211   }
00212   frameSize *= wordsize;
00213   //------------------
00214 
00215   const streamoff offset = frameSize * numFrames;
00216 
00217   /* attempt to seek */
00218   if (!!m_cHandle.seekg(offset, ios::cur))
00219   {
00220     return; /* success */
00221   }
00222   m_cHandle.clear();
00223 
00224   /* fall back to consuming the input */
00225   char buf[512];
00226   const streamoff offset_mod_bufsize = offset % sizeof(buf);
00227   for (streamoff i = 0; i < offset - offset_mod_bufsize; i += sizeof(buf))
00228   {
00229     m_cHandle.read(buf, sizeof(buf));
00230   }
00231   m_cHandle.read(buf, offset_mod_bufsize);
00232 }
