00253 static bool readPlane(Pel* dst,
00254                       istream& fd,
00255                       bool is16bit,
00256                       uint32_t stride444,
00257                       uint32_t width444,
00258                       uint32_t height444,
00259                       uint32_t pad_x444,
00260                       uint32_t pad_y444,
00261                       const ComponentID compID,
00262                       const ChromaFormat destFormat,
00263                       const ChromaFormat fileFormat,
00264                       const uint32_t fileBitDepth)
00265 {
00266   const uint32_t csx_file =getComponentScaleX(compID, fileFormat);
00267   const uint32_t csy_file =getComponentScaleY(compID, fileFormat);
00268   const uint32_t csx_dest =getComponentScaleX(compID, destFormat);
00269   const uint32_t csy_dest =getComponentScaleY(compID, destFormat);
00270 
00271   const uint32_t width_dest       = width444 >>csx_dest;
00272   const uint32_t height_dest      = height444>>csy_dest;
00273   const uint32_t pad_x_dest       = pad_x444>>csx_dest;
00274   const uint32_t pad_y_dest       = pad_y444>>csy_dest;
00275 #if EXTENSION_360_VIDEO
00276   const uint32_t stride_dest = stride444;
00277 #else
00278   const uint32_t stride_dest      = stride444>>csx_dest;
00279 #endif
00280   const uint32_t full_width_dest  = width_dest+pad_x_dest;
00281   const uint32_t full_height_dest = height_dest+pad_y_dest;
00282 
00283   const uint32_t stride_file      = (width444 * (is16bit ? 2 : 1)) >> csx_file;
00284   std::vector<uint8_t> bufVec(stride_file);
00285   uint8_t *buf=&(bufVec[0]);
00286 
00287   Pel  *pDstPad              = dst + stride_dest * height_dest;
00288   Pel  *pDstBuf              = dst;
00289   const int dstbuf_stride    = stride_dest;
00290 
00291   if (compID!=COMPONENT_Y && (fileFormat==CHROMA_400 || destFormat==CHROMA_400))
00292   {
00293     if (destFormat!=CHROMA_400)
00294     {
00295       // set chrominance data to mid-range: (1<<(fileBitDepth-1))
00296       const Pel value=Pel(1<<(fileBitDepth-1));
00297       for (uint32_t y = 0; y < full_height_dest; y++, pDstBuf+= dstbuf_stride)
00298       {
00299         for (uint32_t x = 0; x < full_width_dest; x++)
00300         {
00301           pDstBuf[x] = value;
00302         }
00303       }
00304     }
00305 
00306     if (fileFormat!=CHROMA_400)
00307     {
00308       const uint32_t height_file      = height444>>csy_file;
00309       fd.seekg(height_file*stride_file, ios::cur);
00310       if (fd.eof() || fd.fail() )
00311       {
00312         return false;
00313       }
00314     }
00315   }
00316   else
00317   {
00318     const uint32_t mask_y_file=(1<<csy_file)-1;
00319     const uint32_t mask_y_dest=(1<<csy_dest)-1;
00320     for(uint32_t y444=0; y444<height444; y444++)
00321     {
00322       if ((y444&mask_y_file)==0)
00323       {
00324         // read a new line
00325         fd.read(reinterpret_cast<char*>(buf), stride_file);
00326         if (fd.eof() || fd.fail() )
00327         {
00328           return false;
00329         }
00330       }
00331 
00332       if ((y444&mask_y_dest)==0)
00333       {
00334         // process current destination line
00335         if (csx_file < csx_dest)
00336         {
00337           // eg file is 444, dest is 422.
00338           const uint32_t sx=csx_dest-csx_file;
00339           if (!is16bit)
00340           {
00341             for (uint32_t x = 0; x < width_dest; x++)
00342             {
00343               pDstBuf[x] = buf[x<<sx];
00344             }
00345           }
00346           else
00347           {
00348             for (uint32_t x = 0; x < width_dest; x++)
00349             {
00350               pDstBuf[x] = Pel(buf[(x<<sx)*2+0]) | (Pel(buf[(x<<sx)*2+1])<<8);
00351             }
00352           }
00353         }
00354         else
00355         {
00356           // eg file is 422, dest is 444.
00357           const uint32_t sx=csx_file-csx_dest;
00358           if (!is16bit)
00359           {
00360             for (uint32_t x = 0; x < width_dest; x++)
00361             {
00362               pDstBuf[x] = buf[x>>sx];
00363             }
00364           }
00365           else
00366           {
00367             for (uint32_t x = 0; x < width_dest; x++)
00368             {
00369               pDstBuf[x] = Pel(buf[(x>>sx)*2+0]) | (Pel(buf[(x>>sx)*2+1])<<8);
00370             }
00371           }
00372         }
00373 
00374         // process right hand side padding
00375         const Pel val=dst[width_dest-1];
00376         for (uint32_t x = width_dest; x < full_width_dest; x++)
00377         {
00378           pDstBuf[x] = val;
00379         }
00380 
00381         pDstBuf+= dstbuf_stride;
00382       }
00383     }
00384 
00385     // process lower padding
00386     for (uint32_t y = height_dest; y < full_height_dest; y++, pDstPad+=stride_dest)
00387     {
00388       for (uint32_t x = 0; x < full_width_dest; x++)
00389       {
00390         pDstPad[x] = (pDstPad - stride_dest)[x];
00391       }
00392     }
00393   }
00394   return true;
00395 }
