00397 static bool verifyPlane(Pel* dst,
00398                       uint32_t stride444,
00399                       uint32_t width444,
00400                       uint32_t height444,
00401                       uint32_t padX444,
00402                       uint32_t padY444,
00403                       const ComponentID compID,
00404                       const ChromaFormat cFormat,
00405                       const uint32_t bitDepth)
00406 {
00407   const uint32_t csx =getComponentScaleX(compID, cFormat);
00408   const uint32_t csy =getComponentScaleY(compID, cFormat);
00409 
00410 #if EXTENSION_360_VIDEO
00411   const uint32_t stride = stride444;
00412 #else
00413   const uint32_t stride = stride444>>csx;
00414 #endif
00415   const uint32_t fullWidth  = (width444 + padX444) >> csx;
00416   const uint32_t fullHeight = (height444 +padY444) >> csy;
00417 
00418   Pel  *dstBuf              = dst;
00419 
00420   const Pel mask = ~((1 << bitDepth) - 1);
00421 
00422   for (uint32_t y = 0; y < fullHeight; y++, dstBuf+= stride)
00423   {
00424     for (uint32_t x = 0; x < fullWidth; x++)
00425     {
00426       if ( (dstBuf[x] & mask) != 0)
00427       {
00428         return false;
00429       }
00430     }
00431   }
00432 
00433   return true;
00434 }
