00452 static bool writePlane( uint32_t orgWidth, uint32_t orgHeight, VideoIOYuvMem::Writer *writer, const Pel* src,
00453                        const bool is16bit,
00454                        const uint32_t stride_src,
00455                        uint32_t width444, uint32_t height444,
00456                        const ComponentID compID,
00457                        const ChromaFormat srcFormat,
00458                        const ChromaFormat fileFormat,
00459                        const uint32_t fileBitDepth,
00460                        const uint32_t packedYUVOutputMode = 0)
00461 {
00462   const uint32_t csx_file =getComponentScaleX(compID, fileFormat);
00463   const uint32_t csy_file =getComponentScaleY(compID, fileFormat);
00464   const uint32_t csx_src  =getComponentScaleX(compID, srcFormat);
00465   const uint32_t csy_src  =getComponentScaleY(compID, srcFormat);
00466 
00467   const uint32_t width_file  = width444  >> csx_file;
00468   const uint32_t height_file = height444 >> csy_file;
00469   const bool     writePYUV   = (packedYUVOutputMode > 0) && (fileBitDepth == 10 || fileBitDepth == 12) && ((width_file & (1 + (fileBitDepth & 3))) == 0);
00470 
00471   CHECK( csx_file != csx_src, "Not supported" );
00472   const uint32_t stride_file = writePYUV ? ( orgWidth * fileBitDepth ) >> ( csx_file + 3 ) : ( orgWidth * ( is16bit ? 2 : 1 ) ) >> csx_file;
00473 
00474   std::vector<uint8_t> bufVec(stride_file);
00475   uint8_t *buf=&(bufVec[0]);
00476 
00477   const Pel *pSrcBuf         = src;
00478   const int srcbuf_stride    = stride_src;
00479 
00480   if (writePYUV)
00481   {
00482     const uint32_t mask_y_file = (1 << csy_file) - 1;
00483     const uint32_t mask_y_src  = (1 << csy_src ) - 1;
00484     const uint32_t widthS_file = width_file >> (fileBitDepth == 12 ? 1 : 2);
00485 
00486     for (uint32_t y444 = 0; y444 < height444; y444++)
00487     {
00488       if ((y444 & mask_y_file) == 0)  // write a new line to file
00489       {
00490         if (csx_file < csx_src)
00491         {
00492           // eg file is 444, source is 422.
00493           const uint32_t sx = csx_src - csx_file;
00494 
00495           if (fileBitDepth == 10)  // write 4 values into 5 bytes
00496           {
00497             for (uint32_t x = 0; x < widthS_file; x++)
00498             {
00499               const uint32_t src0 = pSrcBuf[(4*x  ) >> sx];
00500               const uint32_t src1 = pSrcBuf[(4*x+1) >> sx];
00501               const uint32_t src2 = pSrcBuf[(4*x+2) >> sx];
00502               const uint32_t src3 = pSrcBuf[(4*x+3) >> sx];
00503 
00504               buf[5*x  ] = ((src0     ) & 0xff); // src0:76543210
00505               buf[5*x+1] = ((src1 << 2) & 0xfc) + ((src0 >> 8) & 0x03);
00506               buf[5*x+2] = ((src2 << 4) & 0xf0) + ((src1 >> 6) & 0x0f);
00507               buf[5*x+3] = ((src3 << 6) & 0xc0) + ((src2 >> 4) & 0x3f);
00508               buf[5*x+4] = ((src3 >> 2) & 0xff); // src3:98765432
00509             }
00510           }
00511           else if (fileBitDepth == 12) //...2 values into 3 bytes
00512           {
00513             for (uint32_t x = 0; x < widthS_file; x++)
00514             {
00515               const uint32_t src0 = pSrcBuf[(2*x  ) >> sx];
00516               const uint32_t src1 = pSrcBuf[(2*x+1) >> sx];
00517 
00518               buf[3*x  ] = ((src0     ) & 0xff); // src0:76543210
00519               buf[3*x+1] = ((src1 << 4) & 0xf0) + ((src0 >> 8) & 0x0f);
00520               buf[3*x+2] = ((src1 >> 4) & 0xff); // src1:BA987654
00521             }
00522           }
00523         }
00524         else
00525         {
00526           // eg file is 422, source is 444.
00527           const uint32_t sx = csx_file - csx_src;
00528 
00529           if (fileBitDepth == 10)  // write 4 values into 5 bytes
00530           {
00531             for (uint32_t x = 0; x < widthS_file; x++)
00532             {
00533               const uint32_t src0 = pSrcBuf[(4*x  ) << sx];
00534               const uint32_t src1 = pSrcBuf[(4*x+1) << sx];
00535               const uint32_t src2 = pSrcBuf[(4*x+2) << sx];
00536               const uint32_t src3 = pSrcBuf[(4*x+3) << sx];
00537 
00538               buf[5*x  ] = ((src0     ) & 0xff); // src0:76543210
00539               buf[5*x+1] = ((src1 << 2) & 0xfc) + ((src0 >> 8) & 0x03);
00540               buf[5*x+2] = ((src2 << 4) & 0xf0) + ((src1 >> 6) & 0x0f);
00541               buf[5*x+3] = ((src3 << 6) & 0xc0) + ((src2 >> 4) & 0x3f);
00542               buf[5*x+4] = ((src3 >> 2) & 0xff); // src3:98765432
00543             }
00544           }
00545           else if (fileBitDepth == 12) //...2 values into 3 bytes
00546           {
00547             for (uint32_t x = 0; x < widthS_file; x++)
00548             {
00549               const uint32_t src0 = pSrcBuf[(2*x  ) << sx];
00550               const uint32_t src1 = pSrcBuf[(2*x+1) << sx];
00551 
00552               buf[3*x  ] = ((src0     ) & 0xff); // src0:76543210
00553               buf[3*x+1] = ((src1 << 4) & 0xf0) + ((src0 >> 8) & 0x0f);
00554               buf[3*x+2] = ((src1 >> 4) & 0xff); // src1:BA987654
00555             }
00556           }
00557         }
00558 
00559         writer->write (buf, stride_file);
00560 //        if (fd.eof() || fd.fail())
00561 //        {
00562 //          return false;
00563 //        }
00564       }
00565 
00566       if ((y444 & mask_y_src) == 0)
00567       {
00568         pSrcBuf += srcbuf_stride;
00569       }
00570     }
00571 
00572     // here height444 and orgHeight are luma heights
00573     if ((compID == COMPONENT_Y) || (fileFormat != CHROMA_400 && srcFormat != CHROMA_400))
00574     {
00575       for (uint32_t y444 = height444; y444 < orgHeight; y444++)
00576       {
00577         if ((y444 & mask_y_file) == 0) // if this is chroma, determine whether to skip every other row
00578         {
00579           memset (reinterpret_cast<char*>(buf), 0, stride_file);
00580 
00581           writer->write (buf, stride_file);
00582 //          if (fd.eof() || fd.fail())
00583 //          {
00584 //            return false;
00585 //          }
00586         }
00587 
00588         if ((y444 & mask_y_src) == 0)
00589         {
00590           pSrcBuf += srcbuf_stride;
00591         }
00592       }
00593     }
00594   }
00595   else // !writePYUV
00596   if (compID!=COMPONENT_Y && (fileFormat==CHROMA_400 || srcFormat==CHROMA_400))
00597   {
00598     if (fileFormat!=CHROMA_400)
00599     {
00600       const uint32_t value = 1 << (fileBitDepth - 1);
00601 
00602       for (uint32_t y = 0; y < height_file; y++)
00603       {
00604         if (!is16bit)
00605         {
00606           uint8_t val(value);
00607           for (uint32_t x = 0; x < width_file; x++)
00608           {
00609             buf[x]=val;
00610           }
00611         }
00612         else
00613         {
00614           uint16_t val(value);
00615           for (uint32_t x = 0; x < width_file; x++)
00616           {
00617             buf[2*x  ]= (val>>0) & 0xff;
00618             buf[2*x+1]= (val>>8) & 0xff;
00619           }
00620         }
00621 
00622         writer->write(buf, stride_file);
00623 //        if (fd.eof() || fd.fail() )
00624 //        {
00625 //          return false;
00626 //        }
00627       }
00628     }
00629   }
00630   else
00631   {
00632     const uint32_t mask_y_file = (1 << csy_file) - 1;
00633     const uint32_t mask_y_src  = (1 << csy_src ) - 1;
00634 
00635     for (uint32_t y444 = 0; y444 < height444; y444++)
00636     {
00637       if ((y444 & mask_y_file) == 0)
00638       {
00639         // write a new line
00640         if (csx_file < csx_src)
00641         {
00642           // eg file is 444, source is 422.
00643           const uint32_t sx = csx_src - csx_file;
00644           if (!is16bit)
00645           {
00646             for (uint32_t x = 0; x < width_file; x++)
00647             {
00648               buf[x] = (uint8_t)(pSrcBuf[x>>sx]);
00649             }
00650           }
00651           else
00652           {
00653             for (uint32_t x = 0; x < width_file; x++)
00654             {
00655               buf[2*x  ] = (pSrcBuf[x>>sx]>>0) & 0xff;
00656               buf[2*x+1] = (pSrcBuf[x>>sx]>>8) & 0xff;
00657             }
00658           }
00659         }
00660         else
00661         {
00662           // eg file is 422, source is 444.
00663           const uint32_t sx = csx_file - csx_src;
00664           if (!is16bit)
00665           {
00666             for (uint32_t x = 0; x < width_file; x++)
00667             {
00668               buf[x] = (uint8_t)(pSrcBuf[x<<sx]);
00669             }
00670           }
00671           else
00672           {
00673             for (uint32_t x = 0; x < width_file; x++)
00674             {
00675               buf[2*x  ] = (pSrcBuf[x<<sx]>>0) & 0xff;
00676               buf[2*x+1] = (pSrcBuf[x<<sx]>>8) & 0xff;
00677             }
00678           }
00679         }
00680 
00681         writer->write (buf, stride_file);
00682 //        if (fd.eof() || fd.fail())
00683 //        {
00684 //          return false;
00685 //        }
00686       }
00687 
00688       if ((y444 & mask_y_src) == 0)
00689       {
00690         pSrcBuf += srcbuf_stride;
00691       }
00692     }
00693 
00694     // here height444 and orgHeight are luma heights
00695     for( uint32_t y444 = height444; y444 < orgHeight; y444++ )
00696     {
00697       if( ( y444 & mask_y_file ) == 0 ) // if this is chroma, determine whether to skip every other row
00698       {
00699         if( !is16bit )
00700         {
00701           for( uint32_t x = 0; x < ( orgWidth >> csx_file ); x++ )
00702           {
00703             buf[x] = 0;
00704           }
00705         }
00706         else
00707         {
00708           for( uint32_t x = 0; x < ( orgWidth >> csx_file ); x++ )
00709           {
00710             buf[2 * x] = 0;
00711             buf[2 * x + 1] = 0;
00712           }
00713         }
00714         writer->write(buf, stride_file );
00715 //        if( fd.eof() || fd.fail() )
00716 //        {
00717 //          return false;
00718 //        }
00719       }
00720 
00721       if( ( y444 & mask_y_src ) == 0 )
00722       {
00723         pSrcBuf += srcbuf_stride;
00724       }
00725     }
00726 
00727   }
00728   return true;
00729 }
00730 
00731 static bool writeField(VideoIOYuvMem::Writer *writer, const Pel* top, const Pel* bottom,
00732                        const bool is16bit,
00733                        const uint32_t stride_src,
00734                        uint32_t width444, uint32_t height444,
00735                        const ComponentID compID,
00736                        const ChromaFormat srcFormat,
00737                        const ChromaFormat fileFormat,
00738                        const uint32_t fileBitDepth, const bool isTff,
00739                        const uint32_t packedYUVOutputMode = 0)
00740 {
00741   const uint32_t csx_file =getComponentScaleX(compID, fileFormat);
00742   const uint32_t csy_file =getComponentScaleY(compID, fileFormat);
00743   const uint32_t csx_src  =getComponentScaleX(compID, srcFormat);
00744   const uint32_t csy_src  =getComponentScaleY(compID, srcFormat);
00745 
00746   const uint32_t width_file  = width444  >> csx_file;
00747   const uint32_t height_file = height444 >> csy_file;
00748   const bool     writePYUV   = (packedYUVOutputMode > 0) && (fileBitDepth == 10 || fileBitDepth == 12) && ((width_file & (1 + (fileBitDepth & 3))) == 0);
00749   const uint32_t stride_file = writePYUV ? (width444 * fileBitDepth) >> (csx_file + 3) : (width444 * (is16bit ? 2 : 1)) >> csx_file;
00750 
00751   std::vector<uint8_t> bufVec(stride_file * 2);
00752   uint8_t *buf=&(bufVec[0]);
00753 
00754   if (writePYUV)
00755   {
00756     // TODO
00757   }
00758   else // !writePYUV
00759   if (compID!=COMPONENT_Y && (fileFormat==CHROMA_400 || srcFormat==CHROMA_400))
00760   {
00761     if (fileFormat!=CHROMA_400)
00762     {
00763       const uint32_t value = 1 << (fileBitDepth - 1);
00764 
00765       for (uint32_t y = 0; y < height_file; y++)
00766       {
00767         for (uint32_t field = 0; field < 2; field++)
00768         {
00769           uint8_t *fieldBuffer = buf + (field * stride_file);
00770 
00771           if (!is16bit)
00772           {
00773             uint8_t val(value);
00774             for (uint32_t x = 0; x < width_file; x++)
00775             {
00776               fieldBuffer[x]=val;
00777             }
00778           }
00779           else
00780           {
00781             uint16_t val(value);
00782             for (uint32_t x = 0; x < width_file; x++)
00783             {
00784               fieldBuffer[2*x  ]= (val>>0) & 0xff;
00785               fieldBuffer[2*x+1]= (val>>8) & 0xff;
00786             }
00787           }
00788         }
00789 
00790         writer->write(buf, (stride_file * 2));
00791 //        if (fd.eof() || fd.fail() )
00792 //        {
00793 //          return false;
00794 //        }
00795       }
00796     }
00797   }
00798   else
00799   {
00800     const uint32_t mask_y_file=(1<<csy_file)-1;
00801     const uint32_t mask_y_src =(1<<csy_src )-1;
00802     for(uint32_t y444=0; y444<height444; y444++)
00803     {
00804       if ((y444&mask_y_file)==0)
00805       {
00806         for (uint32_t field = 0; field < 2; field++)
00807         {
00808           uint8_t *fieldBuffer = buf + (field * stride_file);
00809           const Pel *src     = (((field == 0) && isTff) || ((field == 1) && (!isTff))) ? top : bottom;
00810 
00811           // write a new line
00812           if (csx_file < csx_src)
00813           {
00814             // eg file is 444, source is 422.
00815             const uint32_t sx=csx_src-csx_file;
00816             if (!is16bit)
00817             {
00818               for (uint32_t x = 0; x < width_file; x++)
00819               {
00820                 fieldBuffer[x] = (uint8_t)(src[x>>sx]);
00821               }
00822             }
00823             else
00824             {
00825               for (uint32_t x = 0; x < width_file; x++)
00826               {
00827                 fieldBuffer[2*x  ] = (src[x>>sx]>>0) & 0xff;
00828                 fieldBuffer[2*x+1] = (src[x>>sx]>>8) & 0xff;
00829               }
00830             }
00831           }
00832           else
00833           {
00834             // eg file is 422, src is 444.
00835             const uint32_t sx=csx_file-csx_src;
00836             if (!is16bit)
00837             {
00838               for (uint32_t x = 0; x < width_file; x++)
00839               {
00840                 fieldBuffer[x] = (uint8_t)(src[x<<sx]);
00841               }
00842             }
00843             else
00844             {
00845               for (uint32_t x = 0; x < width_file; x++)
00846               {
00847                 fieldBuffer[2*x  ] = (src[x<<sx]>>0) & 0xff;
00848                 fieldBuffer[2*x+1] = (src[x<<sx]>>8) & 0xff;
00849               }
00850             }
00851           }
00852         }
00853 
00854         writer->write(buf, (stride_file * 2));
00855 //        if (fd.eof() || fd.fail() )
00856 //        {
00857 //          return false;
00858 //        }
00859       }
00860 
00861       if ((y444&mask_y_src)==0)
00862       {
00863         top    += stride_src;
00864         bottom += stride_src;
00865       }
00866 
00867     }
00868   }
00869   return true;
00870 }
