00888 bool VideoIOYuvMem::read ( PelUnitBuf& pic, PelUnitBuf& picOrg, const InputColourSpaceConversion ipcsc, int aiPad[2], ChromaFormat format, const bool bClipToRec709 )
00889 {
00890   // check end-of-file
00891   if ( isEof() )
00892   {
00893     return false;
00894   }
00895 
00896   if (format >= NUM_CHROMA_FORMAT)
00897   {
00898     format = picOrg.chromaFormat;
00899   }
00900 
00901   bool is16bit = false;
00902 
00903   for(uint32_t ch=0; ch<MAX_NUM_CHANNEL_TYPE; ch++)
00904   {
00905     if (m_fileBitdepth[ch] > 8)
00906     {
00907       is16bit=true;
00908     }
00909   }
00910 
00911   const PelBuf areaBufY = picOrg.get(COMPONENT_Y);
00912 #if !EXTENSION_360_VIDEO
00913   const uint32_t stride444      = areaBufY.stride;
00914 #endif
00915   // compute actual YUV width & height excluding padding size
00916   const uint32_t pad_h444       = aiPad[0];
00917   const uint32_t pad_v444       = aiPad[1];
00918 
00919   const uint32_t width_full444  = areaBufY.width;
00920   const uint32_t height_full444 = areaBufY.height;
00921 
00922   const uint32_t width444       = width_full444 - pad_h444;
00923   const uint32_t height444      = height_full444 - pad_v444;
00924 
00925   for( uint32_t comp=0; comp < ::getNumberValidComponents(format); comp++)
00926   {
00927     const ComponentID compID = ComponentID(comp);
00928     const ChannelType chType=toChannelType(compID);
00929 
00930     const int desired_bitdepth = m_MSBExtendedBitDepth[chType] + m_bitdepthShift[chType];
00931 
00932     const bool b709Compliance=(bClipToRec709) && (m_bitdepthShift[chType] < 0 && desired_bitdepth >= 8);     /* ITU-R BT.709 compliant clipping for converting say 10b to 8b */
00933     const Pel minval = b709Compliance? ((   1 << (desired_bitdepth - 8))   ) : 0;
00934     const Pel maxval = b709Compliance? ((0xff << (desired_bitdepth - 8)) -1) : (1 << desired_bitdepth) - 1;
00935     const bool processComponent = (size_t)compID < picOrg.bufs.size();
00936     Pel* const dst = processComponent ? picOrg.get(compID).bufAt(0,0) : nullptr;
00937 #if EXTENSION_360_VIDEO
00938     const uint32_t stride444 = picOrg.get(compID).stride;
00939 #endif
00940     if ( ! readPlane( dst, m_cHandle, is16bit, stride444, width444, height444, pad_h444, pad_v444, compID, picOrg.chromaFormat, format, m_fileBitdepth[chType]))
00941     {
00942       return false;
00943     }
00944 
00945     if (processComponent)
00946     {
00947       if (! verifyPlane( dst, stride444, width444, height444, pad_h444, pad_v444, compID, format, m_fileBitdepth[chType]) )
00948       {
00949          EXIT("Source image contains values outside the specified bit range!");
00950       }
00951 #if !JVET_R0351_HIGH_BIT_DEPTH_ENABLED
00952       if (m_fileBitdepth[chType] > 14 && m_bitdepthShift[chType] < 0)
00953       {
00954         EXIT("JVET_R0351_HIGH_BIT_DEPTH_ENABLED must be enabled for bit depths above 14 if INTERNALBITDEPTH < INPUTBITDEPTH");
00955       }
00956 #endif
00957       scalePlane( picOrg.get(compID), m_bitdepthShift[chType], minval, maxval);
00958     }
00959   }
00960 
00961 #if EXTENSION_360_VIDEO
00962   if (pic.chromaFormat != NUM_CHROMA_FORMAT)
00963     ColourSpaceConvert(picOrg, pic, ipcsc, true);
00964 #else
00965   ColourSpaceConvert( picOrg, pic, ipcsc, true);
00966 #endif
00967 
00968   picOrg.copyFrom(pic);
00969 
00970   return true;
00971 }
00972 
00986  // here orgWidth and orgHeight are for luma
00987 bool VideoIOYuvMem::write( uint32_t orgWidth, uint32_t orgHeight, const CPelUnitBuf& pic,
00988                         const InputColourSpaceConversion ipCSC,
00989                         const bool bPackedYUVOutputMode,
00990                         int confLeft, int confRight, int confTop, int confBottom, ChromaFormat format, const bool bClipToRec709, const bool subtractConfWindowOffsets )
00991 {
00992   PelStorage interm;
00993 
00994   if (ipCSC!=IPCOLOURSPACE_UNCHANGED)
00995   {
00996     interm.create( pic.chromaFormat, Area( Position(), pic.Y()) );
00997     ColourSpaceConvert(pic, interm, ipCSC, false);
00998   }
00999 
01000   const CPelUnitBuf& picC = (ipCSC==IPCOLOURSPACE_UNCHANGED) ? pic : interm;
01001 
01002   // compute actual YUV frame size excluding padding size
01003   bool is16bit = false;
01004   bool nonZeroBitDepthShift=false;
01005 
01006   for(uint32_t ch=0; ch<MAX_NUM_CHANNEL_TYPE; ch++)
01007   {
01008     if (m_fileBitdepth[ch] > 8)
01009     {
01010       is16bit=true;
01011     }
01012     if (m_bitdepthShift[ch] != 0)
01013     {
01014       nonZeroBitDepthShift=true;
01015     }
01016   }
01017 
01018   bool retval = true;
01019   if (format>=NUM_CHROMA_FORMAT)
01020   {
01021     format= picC.chromaFormat;
01022   }
01023 
01024   PelStorage picZ;
01025   if (nonZeroBitDepthShift)
01026   {
01027     picZ.create( picC.chromaFormat, Area( Position(), picC.Y() ) );
01028     picZ.copyFrom( picC );
01029 
01030     for(uint32_t comp=0; comp < ::getNumberValidComponents( picZ.chromaFormat ); comp++)
01031     {
01032       const ComponentID compID=ComponentID(comp);
01033       const ChannelType ch=toChannelType(compID);
01034       const bool b709Compliance = bClipToRec709 && (-m_bitdepthShift[ch] < 0 && m_MSBExtendedBitDepth[ch] >= 8);     /* ITU-R BT.709 compliant clipping for converting say 10b to 8b */
01035       const Pel minval = b709Compliance? ((   1 << (m_MSBExtendedBitDepth[ch] - 8))   ) : 0;
01036       const Pel maxval = b709Compliance? ((0xff << (m_MSBExtendedBitDepth[ch] - 8)) -1) : (1 << m_MSBExtendedBitDepth[ch]) - 1;
01037 
01038       scalePlane( picZ.get(compID), -m_bitdepthShift[ch], minval, maxval);
01039     }
01040   }
01041 
01042   const CPelUnitBuf& picO = nonZeroBitDepthShift ? picZ : picC;
01043 
01044   const CPelBuf areaY     = picO.get(COMPONENT_Y);
01045   const uint32_t    width444  = areaY.width - confLeft - confRight;
01046   const uint32_t    height444 = areaY.height -  confTop  - confBottom;
01047 
01048   if( subtractConfWindowOffsets )
01049   {
01050     orgWidth -= confLeft + confRight;
01051     orgHeight -= confTop + confBottom;
01052   }
01053 
01054   if ((width444 == 0) || (height444 == 0))
01055   {
01056     msg( WARNING, "\nWarning: writing %d x %d luma sample output picture!", width444, height444);
01057   }
01058 
01059   m_writer->picture_begin(is16bit, width444, height444, format);
01060 
01061   for(uint32_t comp=0; retval && comp < ::getNumberValidComponents(format); comp++)
01062   {
01063     const ComponentID compID      = ComponentID(comp);
01064     const ChannelType ch          = toChannelType(compID);
01065     const uint32_t    csx         = ::getComponentScaleX(compID, format);
01066     const uint32_t    csy         = ::getComponentScaleY(compID, format);
01067     const CPelBuf     area        = picO.get(compID);
01068     const int         planeOffset = (confLeft >> csx) + (confTop >> csy) * area.stride;
01069     if( !writePlane( orgWidth, orgHeight, m_writer, area.bufAt( 0, 0 ) + planeOffset, is16bit, area.stride,
01070                      width444, height444, compID, picO.chromaFormat, format, m_fileBitdepth[ch],
01071                      bPackedYUVOutputMode ? 1 : 0))
01072     {
01073       retval = false;
01074     }
01075   }
01076 
01077   m_writer->picture_end();
01078   return retval;
01079 }
01080 
01081 bool VideoIOYuvMem::write( const CPelUnitBuf& picTop, const CPelUnitBuf& picBottom,
01082                         const InputColourSpaceConversion ipCSC,
01083                         const bool bPackedYUVOutputMode,
01084                         int confLeft, int confRight, int confTop, int confBottom, ChromaFormat format, const bool isTff, const bool bClipToRec709 )
01085 {
01086   PelStorage intermTop;
01087   PelStorage intermBottom;
01088 
01089   if( ipCSC != IPCOLOURSPACE_UNCHANGED )
01090   {
01091     intermTop   .create( picTop.   chromaFormat, Area( Position(), picTop.   Y()) );
01092     intermBottom.create( picBottom.chromaFormat, Area( Position(), picBottom.Y()) );
01093     ColourSpaceConvert( picTop,    intermTop, ipCSC, false);
01094     ColourSpaceConvert( picBottom, intermBottom, ipCSC, false);
01095   }
01096   const CPelUnitBuf& picTopC    = (ipCSC==IPCOLOURSPACE_UNCHANGED) ? picTop    : intermTop;
01097   const CPelUnitBuf& picBottomC = (ipCSC==IPCOLOURSPACE_UNCHANGED) ? picBottom : intermBottom;
01098 
01099   bool is16bit = false;
01100   bool nonZeroBitDepthShift=false;
01101 
01102   for(uint32_t ch=0; ch<MAX_NUM_CHANNEL_TYPE; ch++)
01103   {
01104     if (m_fileBitdepth[ch] > 8)
01105     {
01106       is16bit=true;
01107     }
01108     if (m_bitdepthShift[ch] != 0)
01109     {
01110       nonZeroBitDepthShift=true;
01111     }
01112   }
01113 
01114   PelStorage picTopZ;
01115   PelStorage picBottomZ;
01116 
01117   for (uint32_t field = 0; field < 2; field++)
01118   {
01119     const CPelUnitBuf& picC    = (field == 0) ? picTopC : picBottomC;
01120 
01121     if (format>=NUM_CHROMA_FORMAT)
01122     {
01123       format = picC.chromaFormat;
01124     }
01125 
01126     PelStorage& picZ    = (field == 0) ? picTopZ : picBottomZ;
01127 
01128     if (nonZeroBitDepthShift)
01129     {
01130       picZ.create( picC.chromaFormat, Area( Position(), picC.Y() ) );
01131       picZ.copyFrom( picC );
01132 
01133       for(uint32_t comp=0; comp < ::getNumberValidComponents( picZ.chromaFormat ); comp++)
01134       {
01135         const ComponentID compID=ComponentID(comp);
01136         const ChannelType ch=toChannelType(compID);
01137         const bool b709Compliance=bClipToRec709 && (-m_bitdepthShift[ch] < 0 && m_MSBExtendedBitDepth[ch] >= 8);     /* ITU-R BT.709 compliant clipping for converting say 10b to 8b */
01138         const Pel minval = b709Compliance? ((   1 << (m_MSBExtendedBitDepth[ch] - 8))   ) : 0;
01139         const Pel maxval = b709Compliance? ((0xff << (m_MSBExtendedBitDepth[ch] - 8)) -1) : (1 << m_MSBExtendedBitDepth[ch]) - 1;
01140 
01141         scalePlane( picZ.get(compID), -m_bitdepthShift[ch], minval, maxval);
01142       }
01143     }
01144   }
01145 
01146   const CPelUnitBuf& picTopO     = nonZeroBitDepthShift ? picTopZ    : picTopC;
01147   const CPelUnitBuf& picBottomO  = nonZeroBitDepthShift ? picBottomZ : picBottomC;
01148 
01149   bool retval = true;
01150   CHECK( picTopO.chromaFormat != picBottomO.chromaFormat, "Incompatible formats of bottom and top fields" );
01151 
01152   const ChromaFormat dstChrFormat = picTopO.chromaFormat;
01153 
01154   {
01155       const CPelBuf     areaTopY   = picTopO.Y();
01156       const uint32_t    width444   = areaTopY.width  - (confLeft + confRight);
01157       const uint32_t    height444  = areaTopY.height - (confTop + confBottom);
01158 
01159       m_writer->picture_begin(is16bit, width444, height444, dstChrFormat);
01160   }
01161 
01162   for (uint32_t comp = 0; retval && comp < ::getNumberValidComponents(dstChrFormat); comp++)
01163   {
01164     const ComponentID compID     = ComponentID(comp);
01165     const ChannelType ch         = toChannelType(compID);
01166     const CPelBuf     areaTop    = picTopO.   get( compID );
01167     const CPelBuf     areaBottom = picBottomO.get( compID );
01168     const CPelBuf     areaTopY   = picTopO.Y();
01169     const uint32_t    width444   = areaTopY.width  - (confLeft + confRight);
01170     const uint32_t    height444  = areaTopY.height - (confTop + confBottom);
01171 
01172     CHECK(areaTop.width  != areaBottom.width , "Incompatible formats");
01173     CHECK(areaTop.height != areaBottom.height, "Incompatible formats");
01174     CHECK(areaTop.stride != areaBottom.stride, "Incompatible formats");
01175 
01176     if ((width444 == 0) || (height444 == 0))
01177     {
01178       msg( WARNING, "\nWarning: writing %d x %d luma sample output picture!", width444, height444);
01179     }
01180 
01181     const uint32_t csx = ::getComponentScaleX(compID, dstChrFormat );
01182     const uint32_t csy = ::getComponentScaleY(compID, dstChrFormat );
01183     const int planeOffset  = (confLeft>>csx) + ( confTop>>csy) * areaTop.stride; //offset is for entire frame - round up for top field and down for bottom field
01184 
01185     if (!writeField (m_writer,
01186                      (areaTop.   bufAt(0,0) + planeOffset),
01187                      (areaBottom.bufAt(0,0) + planeOffset),
01188                      is16bit,
01189                      areaTop.stride,
01190                      width444, height444, compID, dstChrFormat, format, m_fileBitdepth[ch], isTff,
01191                      bPackedYUVOutputMode ? 1 : 0))
01192     {
01193       retval=false;
01194     }
01195   }
01196   m_writer->picture_end();
01197 
01198   return retval;
01199 }
