01201 
01202 // static member
01203 void VideoIOYuvMem::ColourSpaceConvert(const CPelUnitBuf &src, PelUnitBuf &dest, const InputColourSpaceConversion conversion, bool bIsForwards)
01204 {
01205   const ChromaFormat  format       = src.chromaFormat;
01206   const uint32_t          numValidComp = ::getNumberValidComponents(format);
01207 
01208   switch (conversion)
01209   {
01210     case IPCOLOURSPACE_YCbCrtoYYY:
01211       if (format!=CHROMA_444)
01212       {
01213         // only 444 is handled.
01214         CHECK( format != CHROMA_444, "Chroma format other than 444 not supported" );
01215       }
01216 
01217       {
01218         for(uint32_t comp=0; comp<numValidComp; comp++)
01219         {
01220           dest.get( ComponentID(comp) ).copyFrom( src.get( ComponentID(bIsForwards?0:comp) ) );
01221         }
01222       }
01223       break;
01224     case IPCOLOURSPACE_YCbCrtoYCrCb:
01225       {
01226         for(uint32_t comp=0; comp<numValidComp; comp++)
01227         {
01228           dest.get( ComponentID((numValidComp-comp)%numValidComp) ).copyFrom( src.get( ComponentID(comp) ) );
01229         }
01230       }
01231       break;
01232 
01233     case IPCOLOURSPACE_RGBtoGBR:
01234       {
01235         if (format!=CHROMA_444)
01236         {
01237           // only 444 is handled.
01238           CHECK(format!=CHROMA_444, "Chroma format other than 444 not supported");
01239         }
01240 
01241         // channel re-mapping
01242         for(uint32_t comp=0; comp<numValidComp; comp++)
01243         {
01244           const ComponentID compIDsrc=ComponentID((comp+1)%numValidComp);
01245           const ComponentID compIDdst=ComponentID(comp);
01246 
01247           dest.get( bIsForwards?compIDdst:compIDsrc ).copyFrom( src.get( bIsForwards?compIDsrc:compIDdst ) );
01248         }
01249       }
01250       break;
01251 
01252     case IPCOLOURSPACE_UNCHANGED:
01253     default:
01254       {
01255         for(uint32_t comp=0; comp<numValidComp; comp++)
01256         {
01257           dest.get( ComponentID(comp) ).copyFrom( src.get( ComponentID(comp) ) );
01258         }
01259       }
01260       break;
01261   }
01262 }
01263 
01264 bool VideoIOYuvMem::writeUpscaledPicture( const SPS& sps, const PPS& pps, const CPelUnitBuf& pic, const InputColourSpaceConversion ipCSC, const bool bPackedYUVOutputMode, int outputChoice, ChromaFormat format, const bool bClipToRec709 )
01265 {
01266   ChromaFormat chromaFormatIDC = sps.getChromaFormatIdc();
01267   bool ret = false;
01268 
01269   static Window confFullResolution;
01270   static Window afterScaleWindowFullResolution;
01271 
01272   // decoder does not have information about upscaled picture scaling and conformance windows, store this information when full resolution picutre is encountered
01273   if( sps.getMaxPicWidthInLumaSamples() == pps.getPicWidthInLumaSamples() && sps.getMaxPicHeightInLumaSamples() == pps.getPicHeightInLumaSamples() )
01274   {
01275     afterScaleWindowFullResolution = pps.getScalingWindow();
01276     afterScaleWindowFullResolution = pps.getConformanceWindow();
01277   }
01278 
01279   if( outputChoice && ( sps.getMaxPicWidthInLumaSamples() != pic.get( COMPONENT_Y ).width || sps.getMaxPicHeightInLumaSamples() != pic.get( COMPONENT_Y ).height ) )
01280   {
01281     if( outputChoice == 2 )
01282     {
01283       PelStorage upscaledPic;
01284       upscaledPic.create( chromaFormatIDC, Area( Position(), Size( sps.getMaxPicWidthInLumaSamples(), sps.getMaxPicHeightInLumaSamples() ) ) );
01285 
01286       int curPicWidth = sps.getMaxPicWidthInLumaSamples()   - SPS::getWinUnitX( sps.getChromaFormatIdc() ) * ( afterScaleWindowFullResolution.getWindowLeftOffset() + afterScaleWindowFullResolution.getWindowRightOffset() );
01287       int curPicHeight = sps.getMaxPicHeightInLumaSamples() - SPS::getWinUnitY( sps.getChromaFormatIdc() ) * ( afterScaleWindowFullResolution.getWindowTopOffset()  + afterScaleWindowFullResolution.getWindowBottomOffset() );
01288 
01289       const Window& beforeScalingWindow = pps.getScalingWindow();
01290       int refPicWidth = pps.getPicWidthInLumaSamples()   - SPS::getWinUnitX( sps.getChromaFormatIdc() ) * ( beforeScalingWindow.getWindowLeftOffset() + beforeScalingWindow.getWindowRightOffset() );
01291       int refPicHeight = pps.getPicHeightInLumaSamples() - SPS::getWinUnitY( sps.getChromaFormatIdc() ) * ( beforeScalingWindow.getWindowTopOffset()  + beforeScalingWindow.getWindowBottomOffset() );
01292 
01293       int xScale = ( ( refPicWidth << SCALE_RATIO_BITS ) + ( curPicWidth >> 1 ) ) / curPicWidth;
01294       int yScale = ( ( refPicHeight << SCALE_RATIO_BITS ) + ( curPicHeight >> 1 ) ) / curPicHeight;
01295 
01296       Picture::rescalePicture( std::pair<int, int>( xScale, yScale ), pic, pps.getScalingWindow(), upscaledPic, afterScaleWindowFullResolution, chromaFormatIDC, sps.getBitDepths(), false, false, sps.getHorCollocatedChromaFlag(), sps.getVerCollocatedChromaFlag() );
01297 
01298       ret = write( sps.getMaxPicWidthInLumaSamples(), sps.getMaxPicHeightInLumaSamples(), upscaledPic,
01299         ipCSC,
01300         bPackedYUVOutputMode,
01301         confFullResolution.getWindowLeftOffset() * SPS::getWinUnitX( chromaFormatIDC ),
01302         confFullResolution.getWindowRightOffset() * SPS::getWinUnitX( chromaFormatIDC ),
01303         confFullResolution.getWindowTopOffset() * SPS::getWinUnitY( chromaFormatIDC ),
01304         confFullResolution.getWindowBottomOffset() * SPS::getWinUnitY( chromaFormatIDC ),
01305         NUM_CHROMA_FORMAT, bClipToRec709, false );
01306     }
01307     else
01308     {
01309       const Window &conf = pps.getConformanceWindow();
01310 
01311       ret = write( sps.getMaxPicWidthInLumaSamples(), sps.getMaxPicHeightInLumaSamples(), pic,
01312         ipCSC,
01313         bPackedYUVOutputMode,
01314         conf.getWindowLeftOffset() * SPS::getWinUnitX( chromaFormatIDC ),
01315         conf.getWindowRightOffset() * SPS::getWinUnitX( chromaFormatIDC ),
01316         conf.getWindowTopOffset() * SPS::getWinUnitY( chromaFormatIDC ),
01317         conf.getWindowBottomOffset() * SPS::getWinUnitY( chromaFormatIDC ),
01318         NUM_CHROMA_FORMAT, bClipToRec709, false );
01319     }
01320   }
01321   else
01322   {
01323     const Window &conf = pps.getConformanceWindow();
01324 
01325     ret = write( pic.get( COMPONENT_Y ).width, pic.get( COMPONENT_Y ).height, pic,
01326       ipCSC,
01327       bPackedYUVOutputMode,
01328       conf.getWindowLeftOffset() * SPS::getWinUnitX( chromaFormatIDC ),
01329       conf.getWindowRightOffset() * SPS::getWinUnitX( chromaFormatIDC ),
01330       conf.getWindowTopOffset() * SPS::getWinUnitY( chromaFormatIDC ),
01331       conf.getWindowBottomOffset() * SPS::getWinUnitY( chromaFormatIDC ),
01332       NUM_CHROMA_FORMAT, bClipToRec709 );
01333   }
01334 
01335   return ret;
01336 }
